import { generateKeyPairSync } from "node:crypto";
import { join } from "node:path";
import { cloudflareTest, readD1Migrations } from "@cloudflare/vitest-plugin";
import { defineConfig } from "vite-plus";

// Generated by `wrangler types`, checked by `wrangler types --check`.
const generated = ["worker-configuration.d.ts"];

/** A signing key in Apple's format: a P-256 private key in PKCS #8 PEM. */
const apnsKey = () =>
  generateKeyPairSync("ec", { namedCurve: "P-256" }).privateKey.export({ type: "pkcs8", format: "pem" }).toString();

export default defineConfig({
  fmt: {
    // The width the code was written at.
    printWidth: 120,
    ignorePatterns: generated,
  },
  lint: {
    ignorePatterns: generated,
    // Type-aware rules and full type checking (TypeScript 7) in `vp check`.
    options: {
      typeAware: true,
      typeCheck: true,
    },
  },
  plugins: [
    // The tests run in workerd, with the bindings of wrangler.jsonc and the real D1 migrations.
    cloudflareTest(async () => ({
      wrangler: { configPath: "./wrangler.jsonc" },
      miniflare: {
        bindings: {
          TEST_MIGRATIONS: await readD1Migrations(join(import.meta.dirname, "migrations")),
          // The secrets of wrangler.jsonc, with test values.
          APNS_TEAM_ID: "DEF123GHIJ",
          APNS_SANDBOX_KEY: apnsKey(),
          APNS_SANDBOX_KEY_ID: "ABC123DEFG",
          APNS_PRODUCTION_KEY: apnsKey(),
          APNS_PRODUCTION_KEY_ID: "HIJ456KLMN",
          APP_ATTEST_APP_ID: "TEAM123456.com.fouteox.biathlon",
          APP_ATTEST_SECRET: "test secret",
        },
      },
    })),
  ],
  test: {
    setupFiles: ["./test/setup.ts"],
    // Spies on the Worker's classes, like `PushSender`, last one test.
    restoreMocks: true,
  },
});
